{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined city.",
      "visual_description": "Twilight over shattered royal spires; an ink-stained coat bends over a glowing parchment map spread on a broken cobblestone wall.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp wakes with a warning.",
      "visual_description": "An oil lamp set on a fallen statue flares to life, a single eye opening inside its flame, casting long shadows across cracked marble.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout is wound for the run.",
      "visual_description": "A small tin fox with blue glass eyes stands on a mossy step while a gloved hand twists the key in its tail; gears tick softly.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The rescuer arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall pane of broken glass as if rising from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They approach the looming castle gates.",
      "visual_description": "Towering iron gates hang half-open, carved with faded royal crests; the lamp floats forward, eye narrowed in suspicion.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox slips beneath the portcullis.",
      "visual_description": "Low-angle view of the metal fox darting between rusted spikes, gears whirring, blue eyes glinting against torchlit stone.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "A cursed tower leans over the courtyard.",
      "visual_description": "A black-stoned tower spirals impossibly, dripping violet smoke; the rescue party stares up from a courtyard littered with torn banners.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a winged beast echo overhead.",
      "visual_description": "A massive serpentine shadow sweeps over the rooftops; only its silhouette is visible against a bruised purple sky as the group ducks beneath an archway.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Old royal banners flutter in a dead hall.",
      "visual_description": "A long throne hall lined with tattered crimson banners; dust motes catch the lamp's light as it floats between fallen chandeliers.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "They find the captive they came for.",
      "visual_description": "A man slumped against a ledger-book pillow snores in a barred alcove, stamped papers stuck to his sleeves, keys jingling above him on a hook.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeper refuses to wake.",
      "visual_description": "The diver shakes the official's shoulder while the mapmaker holds up the compass; the man only mutters, drool pooling on his ledger.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols march through the corridor.",
      "visual_description": "Shadows of plated figures stomp past a doorway; the party flattens behind a tapestry, lamp's eye squeezed shut to hide its glow.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door bars the way out.",
      "visual_description": "An ornate door pulses with rune-light, runes shifting like fish; the mapmaker traces a finger along its surface while the lamp whispers.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The diver swims through a mirror around it.",
      "visual_description": "The clear-helmed figure dives sideways into a tall hallway mirror, ripples spreading across glass as the tin fox leaps in after.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Frightened faces watch from shuttered windows.",
      "visual_description": "Narrow alley at night; pale eyes peek from cracks in boarded shutters as the party hurries past with the dozing official slung between them.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The lamp warns of an ambush ahead.",
      "visual_description": "The oracle lamp flares red, eye wide; ahead, helmet plumes bob above a low wall at the foot of a long stone bridge.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The tin fox draws the patrol away.",
      "visual_description": "The clockwork fox sprints across moonlit flagstones, sparks trailing from its tail, leading armored shadows down a side street away from the bridge.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes across the broken bridge.",
      "visual_description": "Dawn breaks pink over a crumbling arched bridge; the diver, the mapmaker, the floating lamp, and the still-snoring official cross silhouetted against the ruined skyline.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

